function getCachedSstPoint(
  latitude,
  longitude
) {
  const key =
    createSstPointCacheKey(
      latitude,
      longitude
    );

  const cached =
    sstPointCache.get(key);

  if (!cached) {
    return null;
  }

  const ageMilliseconds =
    Date.now() -
    cached.cachedAt;

  if (
    ageMilliseconds >
    SST_POINT_CACHE_TTL_MS
  ) {
    sstPointCache.delete(key);
    return null;
  }

  return {
    ...cached.value,

    cache: {
      status:
        "hit",

      ageSeconds:
        Number(
          (
            ageMilliseconds /
            1000
          ).toFixed(1)
        ),

      ttlSeconds:
        SST_POINT_CACHE_TTL_MS /
        1000
    }
  };
}

