function createSstSpatialSamplePoints(
  latitude,
  longitude
) {
  const latitudeOffset =
    SST_SPATIAL_SAMPLE_RADIUS_NM /
    60;

  const cosineLatitude =
    Math.cos(
      latitude *
      Math.PI /
      180
    );

  const longitudeOffset =
    Math.abs(cosineLatitude) >
    0.01
      ? SST_SPATIAL_SAMPLE_RADIUS_NM /
        (
          60 *
          cosineLatitude
        )
      : null;

  if (
    !Number.isFinite(
      longitudeOffset
    )
  ) {
    return [];
  }

  return [
    {
      direction: "north",
      latitude:
        latitude +
        latitudeOffset,
      longitude
    },
    {
      direction: "east",
      latitude,
      longitude:
        longitude +
        longitudeOffset
    },
    {
      direction: "south",
      latitude:
        latitude -
        latitudeOffset,
      longitude
    },
    {
      direction: "west",
      latitude,
      longitude:
        longitude -
        longitudeOffset
    }
  ];
}

