async function getSeaSurfaceTemperaturePoint(
  latitude,
  longitude
) {
  const url =
    new URL(
      "https://marine-api.open-meteo.com/v1/marine"
    );

  url.searchParams.set(
    "latitude",
    String(latitude)
  );

  url.searchParams.set(
    "longitude",
    String(longitude)
  );

  url.searchParams.set(
    "cell_selection",
    "sea"
  );

  url.searchParams.set(
    "current",
    "sea_surface_temperature"
  );

  url.searchParams.set(
    "timezone",
    "UTC"
  );

  const payload =
    await fetchJson(url);

  const temperatureCelsius =
    Number.isFinite(payload?.current?.sea_surface_temperature)
      ? payload.current.sea_surface_temperature
      : null;

  return {
    requestedLatitude:
      latitude,

    requestedLongitude:
      longitude,

    resolvedLatitude:
      safeNumber(
        payload?.latitude
      ) ??
      latitude,

    resolvedLongitude:
      safeNumber(
        payload?.longitude
      ) ??
      longitude,

    // Do not promote legacy request-coordinate fallbacks into map positions.
    providerCoordinates: resolveProviderCoordinates(payload?.latitude, payload?.longitude),
    timestampProvenance: "marine-current-block-valid-time",

    temperatureCelsius,

    temperatureFahrenheit:
      celsiusToFahrenheit(
        temperatureCelsius
      ),

    observedAt:
      payload?.current?.time ??
      null,

    source: {
      provider:
        "Open-Meteo",

      classification:
        "forecast-model",

      availability:
        temperatureCelsius === null
          ? "unavailable"
          : "available"
    }
  };
}

