    return null;
  }

  if (rangeFahrenheit < 0.5) {
    return "uniform-water";
  }

  if (rangeFahrenheit < 1.0) {
    return "weak-temperature-transition";
  }

  if (rangeFahrenheit < 2.0) {
    return "moderate-temperature-transition";
  }

  return "strong-temperature-break-candidate";
}

