function assessSstTransitionConfidence(
  {
    samples,
    sufficientCoverage,
    rangeFahrenheit,
    orientation,
    assessment
  }
) {
  assessment = requireScientificAssessmentV1(assessment);
  const validSamples =
    samples.filter(
      sample =>
        Number.isFinite(
          sample
            .temperatureFahrenheit
        )
    );

  const expectedSampleCount = 4;

  const coverageRatio =
    expectedSampleCount > 0
      ? validSamples.length /
        expectedSampleCount
      : 0;

  const observationTimes =
    validSamples
      .map(
        sample =>
          Date.parse(
            sample.observedAt
          )
      )
      .filter(
        Number.isFinite
      );

  const newestObservationTime =
    observationTimes.length > 0
      ? Math.max(
          ...observationTimes
        )
      : null;

  if (Number.isFinite(newestObservationTime) && newestObservationTime > Date.parse(assessment.assessmentAt)) throw new TypeError("SST evidence timestamp after scientific assessment");

  const ageHours =
    Number.isFinite(
      newestObservationTime
    )
      ? Number(
          (
            (
              Date.parse(assessment.assessmentAt) -
              newestObservationTime
            ) /
            3600000
          ).toFixed(1)
        )
      : null;

  const eastWestMagnitude =
    Number.isFinite(
      orientation
        ?.eastWestDifferenceFahrenheit
    )
      ? Math.abs(
          orientation
            .eastWestDifferenceFahrenheit
        )
      : null;

  const northSouthMagnitude =
    Number.isFinite(
      orientation
        ?.northSouthDifferenceFahrenheit
    )
      ? Math.abs(
          orientation
            .northSouthDifferenceFahrenheit
        )
      : null;

  const directionalMagnitudes = [
    eastWestMagnitude,
    northSouthMagnitude
  ]
    .filter(
      Number.isFinite
    )
    .sort(
      (a, b) =>
        b - a
    );

  const dominantMagnitude =
    directionalMagnitudes[0] ??
    null;

  const secondaryMagnitude =
    directionalMagnitudes.length >= 2
      ? directionalMagnitudes[1]
      : null;

  const hasTwoAxisMeasurements =
    directionalMagnitudes.length >= 2;

  const axisSeparationFahrenheit =
    hasTwoAxisMeasurements &&
    Number.isFinite(
      dominantMagnitude
    ) &&
    Number.isFinite(
      secondaryMagnitude
    )
      ? Number(
          (
            dominantMagnitude -
            secondaryMagnitude
          ).toFixed(1)
        )
      : null;

  let score = 0;

  const reasons = [];

  if (
    sufficientCoverage &&
    coverageRatio === 1
  ) {
    score += 25;
    reasons.push(
      "complete-four-point-coverage"
    );
  } else if (
    coverageRatio >= 0.75
  ) {
    score += 15;
    reasons.push(
      "partial-but-sufficient-coverage"
    );
  } else {
    reasons.push(
      "insufficient-spatial-coverage"
    );
  }

  if (
    Number.isFinite(
      rangeFahrenheit
    )
  ) {
    if (
      rangeFahrenheit >= 2
    ) {
      score += 25;
      reasons.push(
        "strong-total-temperature-range"
      );
    } else if (
      rangeFahrenheit >= 1
    ) {
      score += 18;
      reasons.push(
        "moderate-total-temperature-range"
      );
    } else if (
      rangeFahrenheit >= 0.5
    ) {
      score += 8;
      reasons.push(
        "weak-total-temperature-range"
      );
    } else {
      reasons.push(
        "minimal-total-temperature-range"
      );
    }
  }

  if (
    orientation?.classification ===
    "directional-temperature-transition" &&
    Number.isFinite(
      dominantMagnitude
    )
  ) {
    if (
      dominantMagnitude >= 2
