async function getCachedSeaSurfaceTemperaturePoint(
  latitude,
  longitude
) {
  const cached =
    getCachedSstPoint(
      latitude,
      longitude
    );

  if (cached) {
    return cached;
  }

  const key =
    createSstPointCacheKey(
      latitude,
      longitude
    );

  const existingRequest =
    sstPointRequestsInFlight.get(
      key
    );

  if (existingRequest) {
    const sharedValue =
      await existingRequest;

    return {
      ...sharedValue,

      cache: {
        status:
          "shared-in-flight",

        ageSeconds:
          0,

        ttlSeconds:
          SST_POINT_CACHE_TTL_MS /
          1000
      }
    };
  }

  const request =
    getSeaSurfaceTemperaturePoint(
      latitude,
      longitude
    )
      .then(
        value => {
          setCachedSstPoint(
            latitude,
            longitude,
            value
          );

          return value;
        }
      )
      .finally(
        () => {
          sstPointRequestsInFlight.delete(
            key
          );
        }
      );

  sstPointRequestsInFlight.set(
    key,
    request
  );

  const value =
    await request;

  return {
    ...value,

    cache: {
      status:
        "miss",

      ageSeconds:
        0,

      ttlSeconds:
        SST_POINT_CACHE_TTL_MS /
        1000
    }
  };
}

