async function getSstSpatialStructureAtAssessment(
  latitude,
  longitude,
  centerTemperatureFahrenheit,
  assessment
) {
  assessment = resolveScientificAssessmentV1(assessment);
  const samplePoints =
    createSstSpatialSamplePoints(
      latitude,
      longitude
    );

  const results =
    await Promise.allSettled(
      samplePoints.map(
        async (point) => ({
          direction:
            point.direction,

          ...await getCachedSeaSurfaceTemperaturePoint(
            point.latitude,
            point.longitude
          )
        })
      )
    );

  const samples =
    results.map(
      (result, index) => {
        if (
          result.status ===
          "fulfilled"
        ) {
          return result.value;
        }

        console.warn(
          `SST spatial sample failed (${samplePoints[index]?.direction ?? "unknown"}):`,
          result.reason
        );

        return {
          direction:
            samplePoints[index]
              ?.direction ??
            null,

          requestedLatitude:
            samplePoints[index]
              ?.latitude ??
            null,

          requestedLongitude:
            samplePoints[index]
              ?.longitude ??
            null,

          resolvedLatitude:
            null,

          resolvedLongitude:
            null,

          temperatureCelsius:
            null,

          temperatureFahrenheit:
            null,

          observedAt:
            null,

          source: {
            provider:
              "Open-Meteo",

            classification:
              "forecast-model",

            availability:
              "request-failed"
          },

          cache: {
            status:
              "not-cached",

            ageSeconds:
              null,

            ttlSeconds:
              SST_POINT_CACHE_TTL_MS /
              1000
          }
        };
      }
    );

  const validTemperatures = [
    centerTemperatureFahrenheit,
    ...samples.map(
      sample =>
        sample
          .temperatureFahrenheit
    )
  ].filter(
    Number.isFinite
  );

  const validNeighborCount =
    samples.filter(
      sample =>
        Number.isFinite(
          sample
            .temperatureFahrenheit
        )
    ).length;

  const centerTemperatureAvailable =
    Number.isFinite(
      centerTemperatureFahrenheit
    );

  const sufficientCoverage =
    validNeighborCount >= 3;

  const minimumFahrenheit =
    sufficientCoverage
      ? Math.min(
          ...validTemperatures
        )
      : null;

  const maximumFahrenheit =
    sufficientCoverage
      ? Math.max(
          ...validTemperatures
        )
      : null;

  const rangeFahrenheit =
    sufficientCoverage
      ? Number(
          (
            maximumFahrenheit -
            minimumFahrenheit
          ).toFixed(1)
        )
      : null;

  const orientation =
    deriveSstTransitionOrientation(
      samples
    );

  const confidence =
    assessSstTransitionConfidence({
      samples,
      sufficientCoverage,
      rangeFahrenheit,
      orientation,
      assessment
    });

  return {
    sampleRadiusNauticalMiles:
      SST_SPATIAL_SAMPLE_RADIUS_NM,

    validNeighborCount,

    expectedNeighborCount:
      samplePoints.length,

    centerTemperatureAvailable,

    minimumFahrenheit,

    maximumFahrenheit,

    rangeFahrenheit,

    classification:
      classifySstSpatialRange(
        rangeFahrenheit
      ),

    interpretation:
      "local-spatial-temperature-structure",

    thresholdVersion:
      "pelora-sst-spatial-range-v1",

    coverage:
      sufficientCoverage
        ? "sufficient"
        : "insufficient",

    orientation,

    confidence,

    samples,

    limitations: [
      "forecast-model-samples",
      "single-time-snapshot",
      "does-not-confirm-persistence",
      "does-not-confirm-ocean-front",
      "does-not-indicate-species-suitability"
    ]
  };
}

