function buildTemperatureEvidence(
  sst
) {
  const temperatureFahrenheit =
    Number.isFinite(
      sst?.temperatureFahrenheit
    )
      ? sst.temperatureFahrenheit
      : null;

  const temperatureBand =
    sst?.derived
      ?.temperatureBand ??
    sst?.temperatureBand ??
    classifySeaSurfaceTemperature(
      temperatureFahrenheit
    );

  const spatialStructure =
    sst?.derived
      ?.spatialStructure ??
    sst?.spatialStructure ??
    null;

  const governedEnvironmentalFeatureObservation =
    sst?.derived
      ?.governedEnvironmentalFeatureObservation ??
    null;

  const governedObservationAvailable =
    governedEnvironmentalFeatureObservation
      ?.available ===
      true &&
    governedEnvironmentalFeatureObservation
      ?.contractVersion ===
      "pelora-governed-environmental-feature-observation-v1" &&
    governedEnvironmentalFeatureObservation
      ?.observationType ===
      "temperature-transition-observation" &&
    governedEnvironmentalFeatureObservation
      ?.feature
      ?.featureType ===
      "temperature-transition" &&
    governedEnvironmentalFeatureObservation
      ?.feature
      ?.featureFamily ===
      "physical-ocean" &&
    governedEnvironmentalFeatureObservation
      ?.authority
      ?.establishesObservationIdentity ===
      true &&
    typeof governedEnvironmentalFeatureObservation
      ?.observationReference ===
      "string" &&
    /^pelora-observation-v1:[a-f0-9]{64}$/.test(
      governedEnvironmentalFeatureObservation
        .observationReference
    );

  const observationProvenance = {
    available:
      governedObservationAvailable,

    observationReference:
