      "Nearby samples show a pronounced temperature range. This is a candidate spatial pattern, not confirmation of a persistent ocean front or habitat feature.";
  } else if (
    coverage !==
      "sufficient"
  ) {
    drivers.push(
      "insufficient-spatial-coverage"
    );
  }

  return {
    available: true,

    classification,

    headline,

    detail,

    values: {
      temperatureFahrenheit,
      temperatureBand,
      spatialRangeFahrenheit,
      spatialClassification,
      coverage,

      minimumFahrenheit:
        Number.isFinite(
          spatialStructure
            ?.minimumFahrenheit
        )
          ? spatialStructure
              .minimumFahrenheit
          : null,

      maximumFahrenheit:
        Number.isFinite(
          spatialStructure
            ?.maximumFahrenheit
        )
          ? spatialStructure
              .maximumFahrenheit
          : null,

      validNeighborCount:
        Number.isFinite(
          spatialStructure
            ?.validNeighborCount
        )
          ? spatialStructure
              .validNeighborCount
          : null,

      expectedNeighborCount:
        Number.isFinite(
          spatialStructure
            ?.expectedNeighborCount
        )
          ? spatialStructure
              .expectedNeighborCount
          : null,

      sampleRadiusNauticalMiles:
        Number.isFinite(
          spatialStructure
            ?.sampleRadiusNauticalMiles
        )
          ? spatialStructure
              .sampleRadiusNauticalMiles
          : null
    },

    orientation,

    confidence,

    observationProvenance,

    drivers,

    limitations,

    interpretation:
      "species-neutral-temperature-structure-evidence"
  };
}

